void WeeEditor::compose(int layer){juce::MemoryBlock before;p.getStateInformation(before);if(layer<0?p.generate():p.regenerateLayer(layer)){past.push_back(std::move(before));if(past.size()>32)past.erase(past.begin());future.clear();}repaint();}
void WeeEditor::history(bool redoAction){auto& from=redoAction?future:past;auto& to=redoAction?past:future;if(from.empty())return;juce::MemoryBlock now;p.getStateInformation(now);to.push_back(std::move(now));p.setStateInformation(from.back().getData(),int(from.back().getSize()));from.pop_back();repaint();}
void WeeEditor::timerCallback(){
 bool busy=renderJob.busy();renderProgress=renderJob.progress();auto statusText=renderJob.message();if(!p.auditionReady()&&statusText.startsWith("A/B ready"))statusText="Snapshot changed. Render A/B again; LIVE synthesis is active.";renderStatus.setText(statusText,juce::dontSendNotification);renderAB.setEnabled(!busy);saveWav.setEnabled(!busy);stems.setEnabled(!busy);original.setEnabled(!busy&&p.auditionReady());flipped.setEnabled(!busy&&p.auditionReady());cancelRender.setEnabled(busy);openFolder.setEnabled(renderJob.folder().isDirectory());dragWav.setEnabled(!busy&&!renderJob.files().isEmpty());
 for(auto*b:{&original,&flipped,&live})b->setColour(juce::TextButton::buttonColourId,juce::Colour(0xffdbf1fa));(p.auditionMode==1?original:p.auditionMode==2?flipped:live).setColour(juce::TextButton::buttonColourId,juce::Colour(0xff84d8f5));
undo.setEnabled(!past.empty());redo.setEnabled(!future.empty());play.setButtonText(p.preview?"STOP PREVIEW":"PLAY PREVIEW");for(int i=0;i<8;++i){rows[size_t(i)]->wav.setEnabled(!busy);rows[size_t(i)]->regenerate.setEnabled(!rows[size_t(i)]->lock.getToggleState());rows[size_t(i)]->name.setColour(juce::TextButton::buttonColourId,i==selectedLayer?juce::Colour(0xff84d8f5):juce::Colour(0xffdbf1fa));}repaint();}
void WeeEditor::exportMidi(bool dragging,int layer){auto a=p.snapshotArrangement();a.context.bpm=p.exportTempo();std::vector<uint8_t> bytes;
 if(layer>=0){auto c=a.layers[size_t(layer)];c.settings.bpm=a.context.bpm;bytes=wee::midi(c);}else bytes=wee::midi(a,p.audibleLayers());
 if(dragging){auto file=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("WEE-Layers-",".mid");if(file.replaceWithData(bytes.data(),bytes.size()))juce::DragAndDropContainer::performExternalDragDropOfFiles({file.getFullPathName()},false,this);else juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"Export failed","Could not create the temporary MIDI file. Use SAVE ALL MIDI.");return;}
 auto filename=layer>=0?juce::String("WEE-")+wee::layerNames[size_t(layer)]+".mid":"WEE-Layers.mid";
 chooser=std::make_unique<juce::FileChooser>("Save MIDI",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile(filename),"*.mid");juce::Component::SafePointer<WeeEditor> safe(this);
 chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe,bytes=std::move(bytes)](const juce::FileChooser&fc){if(!safe)return;auto f=fc.getResult();if(f==juce::File{})return;if(!f.withFileExtension("mid").replaceWithData(bytes.data(),bytes.size()))juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"Export failed","Could not write the MIDI file.");});
}
