void WeeEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xfff0f5f9));g.setColour(juce::Colours::white);g.fillRoundedRectangle(15,15,float(getWidth()-30),70,22);g.setColour(juce::Colour(0xff14a9dc));g.setFont(juce::FontOptions(42.f));g.drawText("wee",34,20,140,54,juce::Justification::centredLeft);g.setFont(juce::FontOptions(17.f));g.drawText("v0.3",getWidth()-115,28,80,40,juce::Justification::centredRight);g.setColour(juce::Colour(0xff526777));g.setFont(juce::FontOptions(14.f));g.drawText("Preview BPM",28,140,225,24,juce::Justification::centredLeft);g.drawText("Master volume",312,140,230,24,juce::Justification::centredLeft);if(!showEffects)g.drawText("Layer / select to view           Enabled / Mute / Solo / Lock         Instrument                 Volume                      Pan             Regenerate / MIDI / WAV",30,220,getWidth()-60,24,juce::Justification::centredLeft);
 if(showEffects)return;
 auto a=p.snapshotArrangement();auto& c=a.layers[size_t(selectedLayer)];g.setColour(juce::Colours::white);g.fillRoundedRectangle(roll,12);g.setColour(juce::Colour(0xffdce6ed));for(int i=0;i<=a.context.bars*4;++i){float x=roll.getX()+roll.getWidth()*i/(a.context.bars*4);g.drawVerticalLine(int(x),roll.getY(),roll.getBottom());}
 for(auto&n:c.notes){float x=roll.getX()+float(n.beat/(a.context.bars*4))*roll.getWidth();float y=roll.getBottom()-float(n.pitch-24)/84*roll.getHeight();g.setColour(juce::Colour(0xff1bb0e0));g.fillRoundedRectangle(x,y,std::max(3.f,float(n.length/(a.context.bars*4))*roll.getWidth()),4,1.5f);}
 g.setColour(juce::Colour(0xff526777));g.drawText(juce::String(wee::layerNames[size_t(selectedLayer)])+"  |  "+juce::String(int(c.notes.size()))+" notes  |  Seed "+juce::String(c.settings.seed),28,int(roll.getY())-34,getWidth()-56,28,juce::Justification::centredLeft);
 juce::String status;int code=p.generationStatus.load();if(p.unsupportedMeter)status="Unsupported time signature: WEE requires 4/4";else if(code==1)status="Unlock all layers before changing style, key, scale or loop length. Existing music was preserved.";else if(code==2)status="Layer is locked. Unlock it to regenerate.";else status=juce::String(a.context.bars)+" bars  |  "+juce::String(p.tempo.load(),1)+" BPM  |  Lock preserves notes; enable additional layers with ON. FX / FLIP / WAV opens audio rendering.";
 g.drawText(status,27,getHeight()-96,getWidth()-54,30,juce::Justification::centredLeft);
}

EffectControl::EffectControl(WeeProcessor&p,const wee::EffectParameter& spec):kind(spec.kind){
 label.setText(spec.label,juce::dontSendNotification);addAndMakeVisible(label);
 if(kind==1){addAndMakeVisible(toggle);buttonAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.params,spec.id,toggle);}
 else if(kind==3){addAndMakeVisible(choice);choice.addItemList({"16-bit PCM","24-bit PCM","32-bit float"},1);choiceAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.params,spec.id,choice);}
 else{addAndMakeVisible(slider);slider.setSliderStyle(juce::Slider::LinearHorizontal);slider.setTextBoxStyle(juce::Slider::TextBoxRight,false,65,24);slider.setNumDecimalPlacesToDisplay(kind==2||spec.high>100?0:2);sliderAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.params,spec.id,slider);}
 auto tooltip=juce::String(spec.section==1?"Rendered WEE FLIP: RENDER A/B applies these settings to audio. ":spec.section==2?"WAV export setting. ":"Live master-bus DSP. ")+spec.label;
 if(juce::String(spec.id)=="flip_half")tooltip+=". Slows the first half of the source to fill the selected bars, one octave down before transpose.";
 if(juce::String(spec.id)=="flip_pitch")tooltip+=". Granular pitch shifting keeps the selected bar count.";
 slider.setTooltip(tooltip);toggle.setTooltip(tooltip);choice.setTooltip(tooltip);
}
void EffectControl::resized(){auto r=getLocalBounds().reduced(3);label.setBounds(r.removeFromLeft(155));if(kind==1)toggle.setBounds(r.removeFromLeft(45));else if(kind==3)choice.setBounds(r);else slider.setBounds(r);}
void WeeEditor::layoutEffects(int width){int y=0;for(int section=0;section<3;++section){sectionLabels[size_t(section)].setBounds(0,y,width,30);y+=32;int index=0;for(size_t i=0;i<wee::effectParameters.size();++i)if(wee::effectParameters[i].section==section){effectControls[i]->setBounds((index%2)*(width/2),y+(index/2)*40,width/2,38);++index;}y+=((index+1)/2)*40+12;}
 int x=0;for(auto*b:{&renderAB,&original,&flipped,&live}){b->setBounds(x,y,width/4-8,34);x+=width/4;}y+=44;x=0;for(auto*b:std::initializer_list<juce::Button*>{&saveWav,&stems,&dragWav,&openFolder,&cancelRender}){b->setBounds(x,y,width/5-7,34);x+=width/5;}y+=44;progressBar.setBounds(3,y,width-6,22);y+=27;renderStatus.setBounds(0,y,width,50);y+=58;effectContent.setSize(width,y);}
void WeeEditor::setPage(bool effects){showEffects=effects;effectViewport.setVisible(effects);mixerViewport.setVisible(!effects);for(auto*b:std::initializer_list<juce::Button*>{&save,&drag,&undo,&redo})b->setVisible(!effects);repaint();}
void WeeEditor::renderAudition(){if(renderJob.busy())return;auto request=captureRender(p);request.audition=true;request.separateTail=false;request.seamless=true;renderJob.start(std::move(request));}
void WeeEditor::exportAudio(int layer,bool exportStems){if(renderJob.busy())return;setPage(true);auto request=captureRender(p);request.layer=layer;request.stems=exportStems;
 chooser=std::make_unique<juce::FileChooser>("Choose export folder (WEE creates a new subfolder)",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory),"*");juce::Component::SafePointer<WeeEditor> safe(this);
 chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectDirectories,[safe,request=std::move(request)](const juce::FileChooser&fc)mutable{if(!safe)return;auto folder=fc.getResult();if(!folder.isDirectory())return;request.directory=folder;safe->renderJob.start(std::move(request));});
}
